CREATE TABLE `privacy_consents` (`id` CHAR(36) NOT NULL, `user_id` CHAR(36) NULL, `subject_hash` CHAR(64) NOT NULL, `purpose` VARCHAR(64) NOT NULL, `policy_version` VARCHAR(32) NOT NULL, `granted` BOOLEAN NOT NULL, `source` VARCHAR(32) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `privacy_consents_subject_hash_purpose_created_at_idx` (`subject_hash`,`purpose`,`created_at`), INDEX `privacy_consents_user_id_purpose_idx` (`user_id`,`purpose`), CONSTRAINT `privacy_consents_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `risk_reviews` (`id` CHAR(36) NOT NULL, `subject_user_id` CHAR(36) NULL, `target_type` VARCHAR(64) NOT NULL, `target_id` CHAR(36) NULL, `category` VARCHAR(64) NOT NULL, `score` TINYINT UNSIGNED NOT NULL, `signals` JSON NOT NULL, `status` VARCHAR(32) NOT NULL DEFAULT 'OPEN', `reviewed_by_id` CHAR(36) NULL, `resolution` VARCHAR(1000) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `reviewed_at` DATETIME(3) NULL, PRIMARY KEY (`id`), INDEX `risk_reviews_status_score_created_at_idx` (`status`,`score`,`created_at`), INDEX `risk_reviews_target_type_target_id_idx` (`target_type`,`target_id`), CONSTRAINT `risk_reviews_subject_user_id_fkey` FOREIGN KEY (`subject_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT `risk_reviews_reviewed_by_id_fkey` FOREIGN KEY (`reviewed_by_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `security_incidents` (`id` CHAR(36) NOT NULL, `severity` VARCHAR(32) NOT NULL, `status` VARCHAR(32) NOT NULL DEFAULT 'OPEN', `detected_at` DATETIME(3) NOT NULL, `summary` VARCHAR(500) NOT NULL, `personal_data` BOOLEAN NOT NULL DEFAULT false, `authority_due_at` DATETIME(3) NULL, `resolved_at` DATETIME(3) NULL, `metadata` JSON NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `security_incidents_status_severity_detected_at_idx` (`status`,`severity`,`detected_at`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `data_processors` (`id` CHAR(36) NOT NULL, `name` VARCHAR(180) NOT NULL, `purpose` VARCHAR(500) NOT NULL, `data_categories` JSON NOT NULL, `region` VARCHAR(64) NOT NULL, `agreement_reference` VARCHAR(255) NULL, `active` BOOLEAN NOT NULL DEFAULT true, `reviewed_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `data_processors_active_reviewed_at_idx` (`active`,`reviewed_at`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
